<script setup lang="ts">
import {computed,ref,watch,onUnmounted} from 'vue';import AppEmptyState from './AppEmptyState.vue';import {resolveCarouselAppearance,carouselFrameStyle} from '@/domain/carousel-appearance';import type {Theme,Vod,OperationsCarouselSlide,CarouselTarget,CarouselAppearance} from '@/domain/types';import {assetUrl,api} from '@/services/api';
const props=defineProps<{theme:Theme;items:Vod[];editing?:boolean;nativeMobile?:boolean;operationsSlides?:OperationsCarouselSlide[];appearance?:CarouselAppearance}>();const emit=defineEmits<{open:[vod:Vod];page:[page:string];id:[id:string];select:[id:string];action:[target:CarouselTarget]}>();const active=ref(0);const boundItems=ref<Vod[]>([]);let bindingGeneration=0;
const sourceIds=computed(()=>(props.operationsSlides!==undefined?props.operationsSlides.filter(s=>s.enabled).map(s=>s.sourceVodId):props.theme.carousel.slides.map(s=>s.vodId)).filter(Boolean).join(','));
watch(sourceIds,async ids=>{const generation=++bindingGeneration;boundItems.value=[];if(!ids)return;try{const result=await api.catalog(1,'','',ids);if(generation===bindingGeneration)boundItems.value=result.items;}catch{/* Explicit artwork remains available if the bound catalogue cannot be reached. */}},{immediate:true});
type CarouselRow={id:string;title:string;image:string;video?:string;page:string;vodId?:string;vod?:Vod;target?:CarouselTarget};
const rows=computed<CarouselRow[]>(()=>{
 const find=(id?:string)=>[...props.items,...boundItems.value].find(v=>v.id===id);
 if(props.operationsSlides!==undefined)return props.operationsSlides.filter(s=>s.enabled).map(s=>{const source=find(s.sourceVodId);return {id:s.id,title:s.title||source?.title||'',image:s.image||source?.poster||'',page:'home',target:s.target};});
 return props.theme.carousel.slides.map(s=>{const vod=find(s.vodId);return {...s,title:s.title||vod?.title||'',image:s.image||vod?.poster||'',vod};});
});

const geometry=computed(()=>resolveCarouselAppearance(props.theme.carousel,props.appearance));
const frameStyle=computed(()=>carouselFrameStyle(geometry.value));
// Side previews need the swiper layout even when the theme uses fading.
const usesFade=computed(()=>props.theme.carousel.effect==='fade'&&geometry.value.style!=='peek');
let timer:ReturnType<typeof setInterval>|undefined;let touchX=0;
function step(by:number){if(rows.value.length)active.value=(active.value+by+rows.value.length)%rows.value.length;}
watch(()=>[usesFade.value,props.theme.carousel.autoplay,props.theme.carousel.interval,props.editing,rows.value.length],()=>{if(timer)clearInterval(timer);active.value=Math.min(active.value,Math.max(0,rows.value.length-1));if(usesFade.value&&props.theme.carousel.autoplay&&!props.editing&&rows.value.length>1)timer=setInterval(()=>step(1),props.theme.carousel.interval*1000);},{immediate:true});
onUnmounted(()=>{bindingGeneration++;if(timer)clearInterval(timer);});
function touchStart(e:any){touchX=e.changedTouches?.[0]?.clientX||0;}
function touchEnd(e:any){const delta=(e.changedTouches?.[0]?.clientX||0)-touchX;if(Math.abs(delta)>35)step(delta>0?-1:1);}
function open(s:typeof rows.value[number]){if(props.editing)emit('select','hero');else if(s.target)emit('action',s.target);else if(s.vod)emit('open',s.vod);else if(s.vodId)emit('id',s.vodId);else emit('page',s.page);}
</script>
<template><view class="carousel" :class="'carousel-'+geometry.style" :style="frameStyle"><swiper v-if="!usesFade" :style="{height:geometry.height+'px'}" :autoplay="theme.carousel.autoplay&&!editing" :interval="theme.carousel.interval*1000" :current="active" :circular="rows.length>1" :indicator-dots="theme.carousel.indicator==='dots'&&!nativeMobile" :indicator-active-color="theme.colors.accent" :previous-margin="geometry.style==='peek'?'24px':'0px'" :next-margin="geometry.style==='peek'?'24px':'0px'" @change="active=$event.detail.current"><swiper-item v-for="(s,i) in rows" :key="s.id"><view class="slide"  @click="open(s)"><video v-if="geometry.style==='video'&&s.video&&active===i" :src="assetUrl(s.video)" :muted="theme.carousel.muted" :autoplay="!editing" loop :controls="false"/><image v-else-if="s.image" :src="assetUrl(s.image)" :mode="geometry.fit==='contain'?'aspectFit':'aspectFill'"/><view class="hero-copy" :class="'title-'+theme.carousel.titlePosition" v-if="theme.carousel.titlePosition!=='hidden'"><text class="hero-label">{{theme.brand.tagline}}</text><text class="hero-title">{{s.title}}</text><text class="hero-play">立即观看 ›</text></view></view></swiper-item></swiper><view v-else class="fade-stage" :style="{height:geometry.height+'px'}" @touchstart="touchStart" @touchend="touchEnd"><template v-for="(s,i) in rows" :key="s.id"><view class="slide fade-item" :class="{'is-active':active===i}" :style="{opacity:active===i?1:0,pointerEvents:active===i?'auto':'none'}"  @click="open(s)"><video v-if="geometry.style==='video'&&s.video&&active===i" :src="assetUrl(s.video)" :muted="theme.carousel.muted" :autoplay="!editing" loop :controls="false"/><image v-else-if="s.image" :src="assetUrl(s.image)" :mode="geometry.fit==='contain'?'aspectFit':'aspectFill'"/><view class="hero-copy" :class="'title-'+theme.carousel.titlePosition" v-if="theme.carousel.titlePosition!=='hidden'"><text class="hero-label">{{theme.brand.tagline}}</text><text class="hero-title">{{s.title}}</text><text class="hero-play">立即观看 ›</text></view></view></template><view v-if="rows.length>1&&!nativeMobile" class="fade-controls"><text tabindex="0" @click.stop="step(-1)" @keydown.enter="step(-1)">‹</text><view v-if="theme.carousel.indicator==='dots'" class="fade-dots"><text v-for="(s,i) in rows" :key="s.id" :style="{background:active===i?theme.colors.accent:'#ffffff70'}" @click.stop="active=i"> </text></view><text tabindex="0" @click.stop="step(1)" @keydown.enter="step(1)">›</text></view></view><view v-if="nativeMobile&&theme.carousel.indicator==='dots'&&rows.length>1" class="native-dots"><view v-for="(row,i) in rows" :key="row.id" :class="{active:active===i}" role="button" :aria-label="'轮播第'+(i+1)+'张'" @click.stop="active=i"/></view><view v-if="theme.carousel.indicator==='numbers'&&rows.length" class="numbers">{{active+1}} / {{rows.length}}</view><view v-if="!rows.length" class="placeholder" @click="editing&&emit('select','hero')"><AppEmptyState class="carousel-empty" title="精彩即将呈现" :description="editing?'添加轮播图片，打造你的首页':'暂时没有推荐内容'" icon="play"/></view></view></template>
<style scoped>.carousel{box-sizing:border-box;min-width:0;margin:var(--margin) auto;position:relative}.slide{box-sizing:border-box;height:100%;position:relative;overflow:hidden;border-radius:var(--radius);background:var(--surface)}.slide image,.slide video{display:block;width:100%;height:100%;object-fit:var(--fit)}.hero-copy{position:absolute;bottom:0;left:0;right:0;padding:40px 18px 24px;background:linear-gradient(transparent,#000b);color:#fff;display:flex;flex-direction:column;gap:6px}.hero-label{font-size:10px;opacity:.7}.hero-title{font-size:24px;font-weight:700}.hero-play{font-size:11px;color:#d9e9f3}.carousel-inset{padding:8px 14px}.carousel-peek .slide{margin:0 5px}.carousel-poster .slide{margin:0 auto;width:65%}.carousel-split .slide{display:flex}.carousel-split .slide image{width:58%;flex:0 0 58%;order:1}.carousel-split .hero-copy{box-sizing:border-box;position:static;width:42%;min-width:0;justify-content:center;background:var(--surface);padding:15px}.carousel-split .hero-title{font-size:20px}.title-side{left:0;width:50%;bottom:20%;right:auto;background:linear-gradient(90deg,#0009,transparent)}.numbers{position:absolute;bottom:10px;right:15px;color:#fff;font-size:10px;background:#0007;padding:3px 7px;border-radius:5px}.placeholder{border-radius:var(--radius);position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:12px;color:var(--muted);background:var(--surface)}.fade-stage{position:relative;overflow:hidden;border-radius:var(--radius)}.fade-item{position:absolute;inset:0;transition:opacity .55s ease}.fade-controls{position:absolute;left:10px;right:10px;bottom:10px;display:flex;align-items:center;justify-content:space-between;color:#fff;pointer-events:none}.fade-controls>text{pointer-events:auto;padding:0 12px;font-size:25px;background:#0006;border-radius:20px}.fade-dots{display:flex;gap:6px;pointer-events:auto}.fade-dots text{width:6px;height:6px;border-radius:50%}.carousel-poster .fade-item{left:17.5%;right:17.5%;width:auto}.native-dots{position:absolute;right:10px;bottom:14px;display:flex;gap:3px;align-items:center}.native-dots>view{width:3px;height:3px;border-radius:2px;background:#ffffff66;cursor:pointer}.native-dots>view.active{width:12px;background:#fff}</style>